  "sql": "SELECT cs.canonical_smiles, md_substr.pref_name AS substrate_compound_name, md_drug.pref_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m JOIN compound_records cr_substr ON m.substrate_record_id = cr_substr.record_id JOIN molecule_dictionary md_substr ON cr_substr.molregno = md_substr.molregno JOIN compound_structures cs ON md_substr.molregno = cs.molregno JOIN compound_records cr_drug ON m.drug_record_id = cr_drug.record_id JOIN molecule_dictionary md_drug ON cr_drug.molregno = md_drug.molregno WHERE m.enzyme_name = 'CYP2B6' ORDER BY cs.canonical_smiles ASC, md_substr.pref_name ASC, md_drug.pref_name ASC, m.met_conversion ASC, m.pathway_key ASC, m.organism ASC, m.enzyme_name ASC LIMIT 200"
